const items = $items();
const grouped = {};
for (const item of items) {
  const ch = item.json.channel_id;
  if (!grouped[ch]) grouped[ch] = {channel_id: ch, tasks: []};
  grouped[ch].tasks.push(`• ${item.json.asset_code} — ${item.json.name} (${item.json.maintenance_type}) vào ${item.json.scheduled_date}`);
}
return Object.values(grouped).map(g => ({json: g}));

